const crypto = require('crypto');
const item = $input.first();
// n8n 的 Raw Body 位于 binary.data，验签不能重新序列化解析后的 JSON。
const binaryBody = item.binary?.data?.data;
const raw = typeof binaryBody === 'string'
  ? Buffer.from(binaryBody, 'base64').toString('utf8')
  : item.json.rawBody ?? (typeof item.json.body === 'string' ? item.json.body : '');
if (!raw) throw new Error('缺少社交 webhook 原始正文');
const headers = item.json.headers ?? {};
const supplied = headers['x-msime-signature'] ?? headers['X-MSIME-Signature'] ?? '';
const secret = $env.MSIME_SOCIAL_WEBHOOK_SECRET ?? '';
if (!secret || !supplied) throw new Error('缺少社交 webhook 签名');
const expected = `sha256=${crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex')}`;
if (supplied.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(expected))) {
  throw new Error('社交 webhook 签名无效');
}

let payload;
try {
  payload = JSON.parse(raw);
} catch (error) {
  throw new Error('社交 webhook 正文不是 JSON');
}
if (payload.schema_version !== 1 || payload.event !== 'release.published') {
  throw new Error('社交 webhook 事件类型不支持');
}
const release = payload.release ?? {};
const platformFor = (repository, tag) => {
  if (repository === 'metasequoiaime/msime-windows' && /^v\d+\.\d+\.\d+$/.test(tag)) return 'Windows';
  if (repository !== 'metasequoiaime/msime') return null;
  const match = /^(windows7|windows|macos|linux|android|ios|harmony)-v\d+\.\d+\.\d+$/.exec(tag);
  return match ? {windows7: 'Windows 7', windows: 'Windows', macos: 'macOS', linux: 'Linux', android: 'Android', ios: 'iOS', harmony: 'HarmonyOS'}[match[1]] : null;
};
const platform = platformFor(payload.repository, String(release.tag ?? ''));
if (!platform || release.draft === true || release.prerelease === true) return [];
const version = String(release.tag).replace(/^[a-z0-9]+-/, '');
const body = String(release.body ?? '').replace(/```[\s\S]*?```/g, '').trim();
const url = String(release.url ?? '');
const landing = String($env.MSIME_SOCIAL_SITE_URL ?? 'https://msime.app/download/');
if (!/^https:\/\/[^/?#\s@]+(?:\/[^?#\s]*)?$/.test(landing)) throw new Error('社交官网入口必须是无查询参数的 HTTPS 地址');
const campaign = `${String(release.tag ?? 'release').replace(/[^a-zA-Z0-9._~-]/g, '-').slice(0, 100)}-${crypto.createHash('sha256').update(String(payload.idempotency_key)).digest('hex').slice(0, 12)}`;
const trackedUrl = channel => `${landing}?utm_source=${encodeURIComponent(channel)}&utm_medium=social&utm_campaign=${campaign}`;
const truncate = (text, length) => text.length <= length ? text : `${text.slice(0, length - 1)}…`;
// X、Bluesky、Mastodon 都不渲染 Markdown，短帖只写纯文本：从发布说明挑最多 3 个功能名，写成「已发布：A、B、C等 N 项更新」。挑选规则与后端 release_telegram.go 的 releaseXHighlightsOf 相同。
const plain = (text) => text
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\*|__|~~|`/g, '')
  .replace(/\s*[（(][^()（）]*#\d+[^()（）]*[)）]\s*$/, '')
  .replace(/\s+/g, ' ').trim().replace(/[：:，,；;]+$/, '');
const notes = body
  .replace(/<!-- msime-download-guide -->[\s\S]*?<!-- \/msime-download-guide -->/g, '')
  .replace(/<!--[\s\S]*?-->/g, '');
// 开发构建、致谢和升级须知不是给用户看的更新，待办还没做：不列也不计数。
const skippedSections = ['待办', '开发', '构建', '感谢', '致谢', '须知'];
// 超过 18 个字或带逗号、冒号、分号的多半是半句话或一整段说明，不列。
const short = (text) => [...text].length <= 18 && !/[，,：:；;…]/.test(text);
const titled = [];
const untitled = [];
let total = 0;
let skip = false;
for (const raw of notes.split(/\r?\n/)) {
  const line = raw.replace(/\s+$/, '');
  const heading = /^#{1,6}\s+(.*)$/.exec(line);
  if (heading) {
    skip = skippedSections.some((section) => heading[1].includes(section));
    continue;
  }
  // 只认顶格的列表项；缩进的子项是上一条的展开。
  const bullet = /^(?:[-*+]|\d+[.)])\s+(?:\[[ xX]\]\s+)?(.*)$/.exec(line);
  if (!bullet || skip) continue;
  const lead = /^\*\*([^*]+?)\*\*\s*[：:]/.exec(bullet[1]);
  let text = plain(lead ? lead[1] : bullet[1].split('。')[0]);
  if (!text) continue;
  total++;
  if (lead) {
    if (short(text)) titled.push(text);
  } else if (/^(?:新增|支持)/.test(text)) {
    text = text.split(/[，,]/)[0];
    if (short(text)) untitled.push(text);
  } else if (text.startsWith('修复') && short(text)) {
    untitled.push(text);
  }
}
const picked = [...titled, ...untitled].slice(0, 3);
// X 的加权长度：链接不论长短记 23，拉丁字母、数字和常用标点记 1，汉字、全角标点和 emoji 记 2，上限 280。
const xWeight = (text) => {
  let weight = 0;
  for (const part of text.split(/(https?:\/\/\S+)/)) {
    if (/^https?:\/\//.test(part)) {
      weight += 23;
      continue;
    }
    for (const char of part) {
      const code = char.codePointAt(0);
      weight += code <= 0x10FF || (code >= 0x2000 && code <= 0x200D) || (code >= 0x2010 && code <= 0x201F) || (code >= 0x2032 && code <= 0x2037) ? 1 : 2;
    }
  }
  return weight;
};
// 短帖两行：一句话加推广链接。文字不超过 140 字，整条不超过 X 的加权上限和平台自己的字符上限；放不下时少列几条，一条也放不下时只写更新数量。
const shortPost = (channel, length) => {
  const link = `\n${trackedUrl(channel)}`;
  const head = `水杉输入法 ${platform} ${version} 已发布`;
  const fits = (line) => [...line].length <= 140 && xWeight(line + link) <= 280 && (line + link).length <= length;
  for (let count = picked.length; count > 0; count--) {
    const items = picked.slice(0, count);
    // 要点自己带顿号时改用分号隔开，不然分不清哪几个词是一条。
    const separator = items.some((item) => item.includes('、')) ? '；' : '、';
    const line = `${head}：${items.join(separator)}${count < total ? `等 ${total} 项更新` : ''}`;
    if (fits(line)) return line + link;
  }
  const line = total > 0 ? `${head}，含 ${total} 项更新` : head;
  if (!fits(line)) throw new Error('社交链接超过平台长度限制');
  return line + link;
};
// 长帖带完整的发布说明：先为完整链接预留长度，更新内容再长也不能把推广入口截断。
const post = (channel, length) => {
  const content = `水杉输入法 ${platform} ${version} 已发布。\n\n${body || '本版更新内容见 Release 说明。'}`;
  const links = `\n\n下载：${trackedUrl(channel)}\n更新说明：${url}`;
  if (links.length >= length) throw new Error('社交链接超过平台长度限制');
  return truncate(content, length - links.length) + links;
};
const enabled = (flag, ...values) => $env[flag] === '1' && values.every(Boolean);
const state = $getWorkflowStaticData('global');
const completed = state.completed ?? {};
const pending = (channel) => !completed[payload.idempotency_key]?.[channel];
const out = [];
if (enabled('MSIME_TELEGRAM_ENABLED', $env.MSIME_TELEGRAM_BOT_TOKEN, $env.MSIME_TELEGRAM_CHAT_ID) && pending('telegram')) out.push({json: {channel: 'telegram', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('telegram'), text: post('telegram', 4096)}});
if (enabled('MSIME_DISCORD_ENABLED', $env.MSIME_DISCORD_WEBHOOK_URL) && pending('discord')) out.push({json: {channel: 'discord', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('discord'), text: post('discord', 2000)}});
if (enabled('MSIME_MASTODON_ENABLED', $env.MSIME_MASTODON_INSTANCE, $env.MSIME_MASTODON_ACCESS_TOKEN) && pending('mastodon')) out.push({json: {channel: 'mastodon', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('mastodon'), text: shortPost('mastodon', 500)}});
if (enabled('MSIME_BLUESKY_ENABLED', $env.MSIME_BLUESKY_IDENTIFIER, $env.MSIME_BLUESKY_APP_PASSWORD) && pending('bluesky')) out.push({json: {channel: 'bluesky', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('bluesky'), text: shortPost('bluesky', 300)}});
if (enabled('MSIME_X_ENABLED') && pending('x')) out.push({json: {channel: 'x', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('x'), text: shortPost('x', 280)}});
if (enabled('MSIME_REDDIT_ENABLED', $env.MSIME_REDDIT_ACCESS_TOKEN, $env.MSIME_REDDIT_SUBREDDIT, $env.MSIME_REDDIT_USER_AGENT) && pending('reddit')) out.push({json: {channel: 'reddit', idempotency_key: payload.idempotency_key, title: truncate(`水杉输入法 ${platform} ${version} 发布`, 300), text: post('reddit', 40000), url: trackedUrl('reddit'), tracking_url: trackedUrl('reddit')}});
// 验收请求也必须验签，但只记录将要分发的平台，不触发任何发帖分支。
if (payload.dry_run === true) {
  const receipt = {idempotency_key: payload.idempotency_key, platform, channels: out.map(item => item.json.channel), checked_at: new Date().toISOString()};
  state.lastVerification = receipt;
  return [{json: {channel: 'probe', ...receipt}}];
}
return out;

